appearance.customCss:
/*
 * Clock widget - "Synthwave Neon" theme.
 * Indigo/violet panel, hot-pink frame, cyan glowing digital readout and a neon
 * analog dial. Install: Appearance tab -> Enable Custom CSS -> paste this.
 */

.clock-widget {
	background:
		repeating-linear-gradient(to bottom, rgba(255, 47, 185, 0.07) 0 1px, transparent 1px 7px),
		radial-gradient(circle at 50% 118%, rgba(77, 243, 255, 0.3), transparent 62%),
		linear-gradient(160deg, #1b1035 0%, #2c1160 48%, #0a0616 100%);
	border: 1px solid #ff2fb9;
	border-radius: 14px;
	color: #f4e7ff;
	box-shadow:
		0 0 22px rgba(255, 47, 185, 0.5),
		inset 0 0 26px rgba(124, 58, 237, 0.4);
	animation: odeko-clock-panel-glow 5s ease-in-out infinite;
}

@keyframes odeko-clock-panel-glow {
	50% {
		box-shadow: 0 0 32px rgba(255, 47, 185, 0.65);
	}
}

.time-display {
	color: #4df3ff;
	font-family: 'Courier New', Consolas, 'SF Mono', monospace;
	font-size: min(2.4em, 12cqw);
	letter-spacing: 0.06em;
	text-shadow:
		0 0 6px rgba(77, 243, 255, 0.9),
		0 0 20px rgba(77, 243, 255, 0.55);
}

.date-display {
	color: #ff9de0;
	font-size: min(0.85em, 5.2cqw);
	letter-spacing: 0.24em;
	text-transform: uppercase;
	text-shadow: 0 0 10px rgba(255, 47, 185, 0.55);
}

.clock-face {
	fill: rgba(16, 8, 36, 0.96);
}

.clock-ring {
	stroke: #ff2fb9;
	filter: drop-shadow(0 0 4px rgba(255, 47, 185, 0.85));
}

.tick,
.major-tick {
	stroke: rgba(77, 243, 255, 0.7);
}

.major-tick {
	stroke: #4df3ff;
	filter: drop-shadow(0 0 3px rgba(77, 243, 255, 0.85));
}

.clock-number {
	fill: #ffd9f4;
	font-family: 'Courier New', Consolas, monospace;
}

.hour-hand {
	stroke: #ff2fb9;
	filter: drop-shadow(0 0 5px rgba(255, 47, 185, 0.9));
}

.minute-hand {
	stroke: #c084fc;
	filter: drop-shadow(0 0 5px rgba(192, 132, 252, 0.85));
}

.second-hand {
	stroke: #4df3ff;
	filter: drop-shadow(0 0 6px rgba(77, 243, 255, 0.95));
}

.center-dot {
	fill: #4df3ff;
	filter: drop-shadow(0 0 6px rgba(77, 243, 255, 0.9));
}

/*
 * Weather widget - "Aurora Glass" theme.
 * Deep-sky translucent glass under an aurora wash: gradient-lit temperature, a
 * pill condition badge and rounded forecast chips.
 * Install: Appearance tab -> Enable Custom CSS -> paste this.
 */

.weather-widget {
	background:
		radial-gradient(circle at 16% 0%, rgba(125, 211, 252, 0.32), transparent 55%),
		radial-gradient(circle at 88% 8%, rgba(139, 92, 246, 0.3), transparent 55%),
		linear-gradient(165deg, rgba(30, 58, 138, 0.75), rgba(8, 15, 34, 0.92) 62%);
	border: 1px solid rgba(148, 233, 255, 0.45);
	border-radius: 18px;
	color: #e8f6ff;
	box-shadow:
		0 12px 30px rgba(2, 6, 23, 0.55),
		inset 0 1px 0 rgba(255, 255, 255, 0.16);
}

.current-summary {
	border-bottom: 1px solid rgba(148, 233, 255, 0.16);
}

.temperature {
	background: linear-gradient(100deg, #7dd3fc 0%, #a7f3d0 52%, #c4b5fd 100%);
	-webkit-background-clip: text;
	background-clip: text;
	color: #dff3ff;
	-webkit-text-fill-color: transparent;
	filter: drop-shadow(0 0 14px rgba(125, 211, 252, 0.5));
	font-size: 2.2em;
}

.location {
	color: rgba(224, 242, 254, 0.85);
	letter-spacing: 0.1em;
	text-transform: uppercase;
}

.condition-icon {
	box-sizing: border-box;
	background: linear-gradient(160deg, rgba(125, 211, 252, 0.35), rgba(45, 212, 191, 0.22));
	border: 1px solid rgba(186, 230, 253, 0.35);
	border-radius: 14px;
	box-shadow: inset 0 0 14px rgba(186, 230, 253, 0.25);
}

.condition {
	background: linear-gradient(90deg, rgba(14, 116, 144, 0.55), rgba(76, 29, 149, 0.5));
	border: 1px solid rgba(186, 230, 253, 0.4);
	border-radius: 999px;
	font-size: 0.62em;
	padding: 3px 7px;
	text-transform: uppercase;
}

.forecast-item {
	background: linear-gradient(180deg, rgba(125, 211, 252, 0.16), rgba(99, 102, 241, 0.14));
	border: 1px solid rgba(148, 233, 255, 0.25);
	border-radius: 12px;
	box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.1);
}

.forecast-temp {
	color: #a7f3d0;
	text-shadow: 0 0 10px rgba(167, 243, 208, 0.45);
}

.state-view {
	color: rgba(224, 242, 254, 0.82);
	letter-spacing: 0.08em;
}

.error {
	color: #fecdd3;
}

.spin {
	filter: drop-shadow(0 0 8px rgba(125, 211, 252, 0.6));
	animation: odeko-weather-spin 1.8s linear infinite;
}

@keyframes odeko-weather-spin {
	to {
		transform: rotate(360deg);
	}
}

/*
 * System monitor widget - "CRT Phosphor" theme.
 * Near-black tube with a scanline overlay, green glowing monospace readouts and
 * chunky segmented bars. Install: Appearance tab -> Enable Custom CSS -> paste this.
 */

.system-widget {
	background:
		radial-gradient(ellipse at 50% 40%, rgba(57, 255, 20, 0.1), transparent 72%),
		linear-gradient(180deg, #020806 0%, #010403 100%);
	border: 1px solid rgba(57, 255, 20, 0.55);
	border-radius: 8px;
	color: #86ffb4;
	font-family: 'Courier New', Consolas, 'SF Mono', monospace;
	box-shadow:
		inset 0 0 46px rgba(0, 0, 0, 0.9),
		0 0 18px rgba(57, 255, 20, 0.22);
	text-shadow: 0 0 6px rgba(57, 255, 20, 0.45);
}

/* Heavier scanlines than the stock look, with a slow tube flicker. */
.system-widget::before {
	background: repeating-linear-gradient(
		to bottom,
		rgba(0, 0, 0, 0.06) 0px,
		rgba(0, 0, 0, 0.06) 1px,
		rgba(0, 0, 0, 0.34) 1px,
		rgba(0, 0, 0, 0.34) 3px
	);
	animation: odeko-system-scanlines 3.5s steps(3) infinite;
}

@keyframes odeko-system-scanlines {
	50% {
		opacity: 0.72;
	}
}

.stats-container {
	color: #86ffb4;
	font-variant-numeric: tabular-nums;
}

.stat-row {
	box-sizing: border-box;
	border-left: 2px solid rgba(57, 255, 20, 0.35);
	padding-left: 8px;
}

.stat-label {
	color: rgba(134, 255, 180, 0.72);
	letter-spacing: 0.18em;
	text-transform: uppercase;
}

.stat-value {
	color: #35ff9b;
	text-shadow:
		0 0 6px rgba(53, 255, 155, 0.85),
		0 0 16px rgba(53, 255, 155, 0.4);
}

.progress-bar {
	background: linear-gradient(180deg, rgba(0, 0, 0, 0.85), rgba(4, 22, 12, 0.9));
	border-radius: 3px;
	box-shadow:
		inset 0 0 0 1px rgba(57, 255, 20, 0.45),
		inset 0 0 10px rgba(0, 0, 0, 0.95);
}

.progress-fill {
	background:
		repeating-linear-gradient(
			to right,
			rgba(0, 0, 0, 0.35) 0px,
			rgba(0, 0, 0, 0.35) 2px,
			transparent 2px,
			transparent 8px
		),
		linear-gradient(90deg, #0bff7a, #8affbe);
	border-radius: 2px;
	box-shadow:
		0 0 10px rgba(53, 255, 155, 0.75),
		inset 0 0 6px rgba(255, 255, 255, 0.25);
}

/*
 * Music Player widget — "Vinyl Lounge" custom CSS theme.
 * Install: Appearance tab -> Enable Custom CSS -> paste this whole file.
 * The progress fill and play button carry inline theme-color backgrounds, so
 * they are re-tinted with hue-rotate instead of a background override.
 */

.music-widget {
	background: radial-gradient(circle at 24% 4%, #4a1240 0%, #2a0a2e 52%, #140618 100%);
	color: #fdf2f8;
	box-shadow: inset 0 0 0 1px rgba(244, 114, 182, 0.3);
}

.album-art {
	border-radius: 50%;
	box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.22);
	filter: drop-shadow(0 0 12px rgba(217, 70, 239, 0.5));
	animation: odeko-music-glow 5s ease-in-out infinite;
}

@keyframes odeko-music-glow {
	50% {
		filter: drop-shadow(0 0 20px rgba(244, 114, 182, 0.75));
	}
}

.song-title {
	letter-spacing: 0.01em;
	text-shadow: 0 1px 10px rgba(217, 70, 239, 0.45);
}

.song-artist {
	color: rgba(251, 207, 232, 0.85);
	letter-spacing: 0.12em;
	text-transform: uppercase;
}

.progress-bar {
	background: linear-gradient(90deg, rgba(253, 242, 248, 0.08), rgba(253, 242, 248, 0.22));
	border-radius: 999px;
	box-shadow: inset 0 0 0 1px rgba(253, 242, 248, 0.12);
}

.progress-fill {
	filter: hue-rotate(180deg) saturate(1.15);
	border-radius: 999px;
	box-shadow: 0 0 12px rgba(134, 239, 172, 0.5);
}

.control-btn {
	background: rgba(253, 242, 248, 0.1);
	color: #fdf2f8;
	box-shadow: inset 0 0 0 1px rgba(251, 207, 232, 0.25);
}

.control-btn:hover:not(:disabled) {
	background: rgba(244, 114, 182, 0.32);
	color: #ffffff;
	box-shadow: 0 0 16px rgba(244, 114, 182, 0.45);
}

.play-btn {
	filter: hue-rotate(180deg) saturate(1.2);
	box-shadow: 0 0 20px rgba(134, 239, 172, 0.45);
}

.player-dropdown-btn {
	background: rgba(253, 242, 248, 0.12);
	border-color: rgba(251, 207, 232, 0.3);
	color: #fdf2f8;
	box-shadow: 0 0 14px rgba(217, 70, 239, 0.3);
}

.player-dropdown-menu {
	background: rgba(30, 8, 34, 0.96);
	border-color: rgba(244, 114, 182, 0.35);
	border-radius: 14px;
	box-shadow: 0 12px 30px rgba(8, 2, 12, 0.65);
}

.player-option {
	box-shadow: inset 0 -1px 0 rgba(251, 207, 232, 0.12);
}

.player-option:hover,
.player-option.selected {
	background: rgba(244, 114, 182, 0.24);
	box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.3);
}

/*
 * Memo widget — "Kraft Sticky Note" custom CSS theme.
 * Install: Appearance tab -> Enable Custom CSS -> paste this whole file.
 */

.memo-widget {
	background:
		linear-gradient(160deg, rgba(255, 255, 255, 0.4), rgba(255, 255, 255, 0) 46%),
		linear-gradient(150deg, #fff3a6, #ffe066 46%, #f6cc3f);
	border-radius: 4px;
	color: #4a3a10;
	font-family: 'Segoe Print', 'Bradley Hand', 'Comic Sans MS', 'Chalkboard SE', cursive;
	box-shadow:
		inset 0 0 0 1px rgba(198, 152, 32, 0.5),
		inset 0 -12px 22px rgba(150, 108, 12, 0.22);
}

.memo-content {
	color: #43350e;
	font-family: inherit;
	line-height: 1.55;
	caret-color: #a16207;
	text-shadow: 0 1px 0 rgba(255, 255, 255, 0.45);
}

.memo-content::placeholder {
	color: rgba(90, 72, 20, 0.5);
	opacity: 1;
}

/* Folded corner. The memo has no positioning context of its own, so the flap
   anchors to the widget frame around it and keeps its own corner radius. */
.memo-widget::after {
	content: '';
	position: absolute;
	right: 0;
	bottom: 0;
	width: 28px;
	height: 28px;
	border-bottom-right-radius: 4px;
	background: linear-gradient(135deg, #d8b84a, #f7e79f 58%, #fffbe0);
	clip-path: polygon(100% 0, 100% 100%, 0 100%);
	filter: drop-shadow(-3px -3px 4px rgba(96, 68, 8, 0.35));
}

.memo-content::-webkit-scrollbar-thumb {
	background: rgba(150, 108, 12, 0.35);
	border-radius: 999px;
}

/*
 * Task List widget — "Sticky Pastel" custom CSS theme.
 * Install: Appearance tab -> Enable Custom CSS -> paste this whole file.
 */

.tasklist-widget {
	background: linear-gradient(165deg, #312e81, #4c1d95 52%, #2e1065);
	color: #f5f3ff;
	box-shadow: inset 0 0 0 1px rgba(196, 181, 253, 0.35);
}

.task-tab {
	padding: 0 12px;
	background: rgba(255, 255, 255, 0.08);
	border-radius: 999px;
	color: rgba(237, 233, 254, 0.8);
	box-shadow: inset 0 0 0 1px rgba(196, 181, 253, 0.25);
}

.task-tab:hover {
	background: color-mix(in srgb, var(--tab-color) 34%, rgba(255, 255, 255, 0.14));
	color: #ffffff;
}

.task-tab.active {
	background: color-mix(in srgb, var(--tab-color) 62%, rgba(255, 255, 255, 0.18));
	color: #ffffff;
	box-shadow: inset 0 0 0 1px rgba(249, 168, 212, 0.75);
}

.add-tab-btn,
.task-input {
	background: rgba(255, 255, 255, 0.07);
	border-color: rgba(196, 181, 253, 0.45);
	border-radius: 999px;
	color: #f5f3ff;
}

.add-tab-btn:hover {
	background: rgba(249, 168, 212, 0.28);
	border-color: rgba(249, 168, 212, 0.85);
}

.delete-btn {
	background: rgba(244, 114, 182, 0.22);
	border-radius: 999px;
	color: #fbcfe8;
	box-shadow: inset 0 0 0 1px rgba(244, 114, 182, 0.4);
	opacity: 0.4;
}

.task-item {
	padding: 9px 12px;
	background: rgba(255, 255, 255, 0.1);
	border-radius: 14px;
	box-shadow: inset 0 0 0 1px rgba(196, 181, 253, 0.18);
}

.task-item:hover {
	background: rgba(255, 255, 255, 0.17);
}

.checkbox-custom {
	background: rgba(15, 10, 45, 0.5);
	border-color: rgba(196, 181, 253, 0.65);
	border-radius: 6px;
}

.task-item.completed {
	opacity: 0.6;
}

.task-item.completed .checkbox-custom {
	background: linear-gradient(140deg, #f9a8d4, #c4b5fd);
	border-color: rgba(249, 168, 212, 0.9);
}

.task-item.completed .checkbox-custom::after {
	content: '✓';
	color: #3b0764;
	font-size: 12px;
	font-weight: 700;
}

.task-item.completed .task-text {
	color: rgba(237, 233, 254, 0.62);
	text-decoration: line-through;
	text-decoration-color: rgba(249, 168, 212, 0.85);
}

/*
 * Text Box widget — "Typewriter Paper" custom CSS theme.
 * Install: Appearance tab -> Enable Custom CSS -> paste this whole file.
 * The ruled lines live on the textarea with background-attachment: local so
 * they scroll with the text instead of staying pinned to the panel.
 */

.textbox-widget {
	background:
		linear-gradient(
			to right,
			transparent 0 9px,
			rgba(190, 90, 80, 0.28) 9px 10px,
			transparent 10px
		),
		linear-gradient(150deg, #fffdf6, #fdf3de 55%, #f6e7c8);
	border: 1px solid #d8c49a;
	border-radius: 6px;
	color: #3b3226;
	box-shadow:
		inset 0 0 0 1px rgba(255, 255, 255, 0.6),
		inset 0 0 34px rgba(178, 138, 88, 0.18);
	font-family: Georgia, 'Times New Roman', 'Iowan Old Style', serif;
}

.textbox-content {
	background-image: repeating-linear-gradient(
		to bottom,
		transparent 0 calc(1.5em - 1px),
		rgba(176, 137, 104, 0.32) calc(1.5em - 1px) 1.5em
	);
	background-attachment: local;
	color: #33291c;
	font-family: Georgia, 'Times New Roman', serif;
	line-height: 1.5;
	caret-color: #b45309;
	text-shadow: 0 1px 0 rgba(255, 255, 255, 0.65);
}

.textbox-content::placeholder {
	color: rgba(90, 74, 52, 0.45);
	opacity: 1;
}

.textbox-content::selection {
	background: rgba(180, 83, 9, 0.22);
	color: #2b2114;
}

.textbox-content:focus {
	color: #2b2114;
}

.textbox-content::-webkit-scrollbar-thumb {
	background: rgba(176, 137, 104, 0.4);
	border-radius: 999px;
}

/*
 * Slideshow widget - "Cinema" theme.
 * Near-black projection stage with a soft vignette, an inset rounded photo with
 * a deep shadow, and circular glassy nav buttons.
 * Install: Appearance tab -> Enable Custom CSS -> paste this.
 */

.slideshow-widget {
	background: radial-gradient(circle at 50% 45%, #14161d, #05060a 72%);
	border: 1px solid rgba(255, 255, 255, 0.09);
	border-radius: 14px;
	box-shadow:
		0 22px 45px rgba(0, 0, 0, 0.72),
		inset 0 0 0 1px rgba(255, 255, 255, 0.04);
}

/* Inset the photo so the stage frames it, like a projected still. */
.image-stack {
	transform: scale(0.955);
}

/* Vignette over the photo; the nav buttons still paint above it. */
.image-stack::after {
	content: '';
	position: absolute;
	inset: 0;
	pointer-events: none;
	background: radial-gradient(ellipse at 50% 50%, transparent 45%, rgba(0, 0, 0, 0.7) 100%);
}

.slide-img {
	background: #07080c;
	border-radius: 12px;
	box-shadow: 0 18px 42px rgba(0, 0, 0, 0.85);
	filter: contrast(1.06) saturate(1.05);
}

.nav-btn {
	background: rgba(255, 255, 255, 0.16);
	border-radius: 999px;
	color: #f6f8ff;
	opacity: 0.55;
	box-shadow:
		inset 0 0 0 1px rgba(255, 255, 255, 0.3),
		0 6px 18px rgba(0, 0, 0, 0.65);
	backdrop-filter: blur(8px);
	transition:
		background 0.2s ease,
		opacity 0.2s ease,
		box-shadow 0.2s ease;
}

.nav-btn:hover {
	background: rgba(255, 255, 255, 0.32);
	box-shadow:
		inset 0 0 0 1px rgba(255, 255, 255, 0.5),
		0 8px 22px rgba(0, 0, 0, 0.7);
}

.empty-state {
	background: radial-gradient(circle at 50% 45%, rgba(255, 255, 255, 0.08), transparent 65%);
	color: #aab4c4;
}

.empty-icon {
	filter: grayscale(1) brightness(1.6) contrast(1.1);
	animation: odeko-slideshow-float 5s ease-in-out infinite;
}

@keyframes odeko-slideshow-float {
	0%,
	100% {
		transform: translateY(0);
	}
	50% {
		transform: translateY(-4px);
	}
}

.empty-text {
	color: #9aa4b4;
	letter-spacing: 0.18em;
	text-transform: uppercase;
}

/*
 * Divider widget — "Neon Rule" custom CSS theme.
 * Install: Appearance tab -> Enable Custom CSS -> paste this whole file.
 * Works with the Solid, Dashed and Dotted styles; the label gets spaced caps.
 */

.divider-line {
	border-color: #f472b6;
	filter: drop-shadow(0 0 4px rgba(244, 114, 182, 0.9));
}

.divider-label {
	color: #fbcfe8;
	letter-spacing: 0.24em;
	text-transform: uppercase;
	text-shadow: 0 0 8px rgba(244, 114, 182, 0.8);
}

/*
 * Sleep widget - "Moonlight" theme.
 * Indigo night sky with a scatter of stars, a soft glow and a very gentle
 * pulse around the icon, under an uppercase letterspaced label.
 * Install: Appearance tab -> Enable Custom CSS -> paste this.
 */

.power-widget,
.power-widget:hover {
	background:
		radial-gradient(circle at 18% 22%, rgba(255, 255, 255, 0.85) 0 1px, transparent 1.6px),
		radial-gradient(circle at 74% 12%, rgba(206, 224, 255, 0.7) 0 0.8px, transparent 1.4px),
		radial-gradient(circle at 86% 62%, rgba(255, 255, 255, 0.6) 0 0.7px, transparent 1.3px),
		radial-gradient(circle at 50% 30%, #33429b, #1a2159 48%, #070a1c);
	background-repeat: repeat, repeat, repeat, no-repeat;
	background-size:
		96px 96px,
		132px 132px,
		74px 74px,
		100% 100%;
	border: 1px solid rgba(150, 175, 255, 0.32);
	border-radius: 16px;
	color: #e8edff;
	box-shadow:
		0 14px 32px rgba(3, 5, 18, 0.65),
		inset 0 0 30px rgba(90, 120, 255, 0.14);
}

.power-widget:hover {
	border-color: rgba(180, 200, 255, 0.55);
	box-shadow:
		0 16px 36px rgba(3, 5, 18, 0.7),
		inset 0 0 40px rgba(110, 140, 255, 0.3);
}

.default-icon,
.custom-icon {
	filter: drop-shadow(0 0 10px rgba(150, 175, 255, 0.85))
		drop-shadow(0 0 24px rgba(80, 110, 255, 0.45));
	animation: odeko-sleep-pulse 4.5s ease-in-out infinite;
}

.custom-icon {
	border-radius: 14px;
	box-shadow: 0 0 18px rgba(120, 150, 255, 0.45);
}

@keyframes odeko-sleep-pulse {
	0%,
	100% {
		transform: scale(1);
	}
	50% {
		transform: scale(1.07);
	}
}

.label {
	color: #cfd9ff;
	font-size: 0.78em;
	font-weight: 600;
	letter-spacing: 0.2em;
	text-shadow: 0 0 12px rgba(140, 165, 255, 0.55);
	text-transform: uppercase;
}

/*
 * Restart widget - "Sunrise Amber" theme.
 * Warm sunrise gradient behind a glowing icon that turns slowly on hover,
 * under an uppercase letterspaced label.
 * Install: Appearance tab -> Enable Custom CSS -> paste this.
 */

.power-widget,
.power-widget:hover {
	background:
		radial-gradient(
			circle at 50% 106%,
			rgba(255, 226, 160, 0.85),
			rgba(255, 176, 70, 0.3) 26%,
			transparent 52%
		),
		linear-gradient(180deg, #241105, #452108 40%, #6d360c 70%, #b06f1e 90%, #ffc978);
	border: 1px solid rgba(255, 190, 100, 0.4);
	border-radius: 16px;
	color: #ffeccf;
	box-shadow:
		0 14px 32px rgba(24, 10, 0, 0.6),
		inset 0 0 26px rgba(255, 170, 60, 0.18);
}

.power-widget:hover {
	border-color: rgba(255, 214, 140, 0.65);
	box-shadow:
		0 16px 36px rgba(24, 10, 0, 0.66),
		inset 0 0 34px rgba(255, 190, 90, 0.3);
}

.default-icon,
.custom-icon {
	filter: drop-shadow(0 0 10px rgba(255, 196, 92, 0.9))
		drop-shadow(0 0 26px rgba(255, 140, 30, 0.5));
	transform-origin: 50% 50%;
}

.power-widget:hover .default-icon,
