/*
 * Shutdown widget - "Red Alert" theme.
 * Charcoal panel, glowing red frame, a pulsing power glyph and an uppercase
 * letterspaced label that flares on hover.
 * Install: Appearance tab -> Enable Custom CSS -> paste this whole file.
 */

.power-widget {
	background:
		radial-gradient(circle at 50% 0%, rgba(255, 61, 61, 0.38), rgba(255, 61, 61, 0) 62%),
		linear-gradient(165deg, #2b1418, #140a0c 72%);
	border: 1px solid rgba(255, 82, 82, 0.65);
	border-radius: 16px;
	color: #ffd9d9;
	box-shadow:
		0 0 22px rgba(255, 61, 61, 0.35),
		inset 0 0 24px rgba(255, 61, 61, 0.16);
	transition:
		background 0.25s ease,
		border-color 0.25s ease,
		box-shadow 0.25s ease;
}

.power-widget:hover {
	background:
