/*
 * Drawing widget - "Blueprint" theme.
 * Deep navy drafting board with a faint grid, a floating rounded toolbar and
 * cyan accents over dark tool buttons.
 * Install: Appearance tab -> Enable Custom CSS -> paste this.
 */

.drawing-widget {
	background: linear-gradient(165deg, #0d2b4d, #0a1f3a 48%, #061428);
	border: 1px solid rgba(122, 190, 255, 0.4);
	border-radius: 16px;
	font-family: Consolas, 'DejaVu Sans Mono', 'Courier New', monospace;
	box-shadow: 0 18px 38px rgba(2, 8, 20, 0.62);
}

/* Drafting grid on the board: a 24px rule in both directions. */
.canvas-wrapper {
	background-image:
		linear-gradient(rgba(126, 200, 255, 0.16) 1px, transparent 1px),
		linear-gradient(90deg, rgba(126, 200, 255, 0.16) 1px, transparent 1px);
	background-size: 24px 24px;
}
/* Fabric paints its own canvas over the wrapper, so repeat the grid above it. */
.canvas-wrapper::after {
	content: '';
	position: absolute;
	inset: 0;
	pointer-events: none;
	background: inherit;
	box-shadow: inset 0 0 70px rgba(3, 10, 24, 0.55);
}

.drawing-toolbar {
	background: linear-gradient(180deg, rgba(10, 32, 60, 0.94), rgba(6, 20, 40, 0.86));
	border: 1px solid rgba(126, 200, 255, 0.22);
	border-radius: 12px;
	margin: 6px;
	box-shadow: 0 8px 20px rgba(2, 8, 20, 0.55);
}

.tool-btn {
	background: rgba(4, 16, 34, 0.62);
	border-radius: 8px;
	color: #7fb3e0;
	box-shadow: inset 0 0 0 1px rgba(126, 200, 255, 0.16);
}

.tool-btn:hover {
	background: rgba(126, 200, 255, 0.24);
	color: #eaf6ff;
}

.tool-btn-danger:hover {
	background: rgba(214, 66, 66, 0.85);
	color: #fff3f3;
}

.toolbar-divider {
	background: linear-gradient(180deg, transparent, rgba(126, 200, 255, 0.5), transparent);
}

.color-picker-btn {
	border-color: rgba(126, 200, 255, 0.5);
	box-shadow: 0 0 12px rgba(90, 170, 255, 0.35);
}

.color-swatch {
	border-radius: 6px;
}

.slider-label,
.slider-value {
	color: #9fc9f2;
}

.slider {
	-webkit-appearance: none;
	appearance: none;
	border-radius: 999px;
	background: linear-gradient(90deg, #63b3ff, #163f70);
}
.slider::-webkit-slider-thumb {
	-webkit-appearance: none;
	width: 13px;
	height: 13px;
	margin-top: -4.5px;
	border-radius: 50%;
	background: #eaf6ff;
}

/*
 * Custom HTML widget - "Poster" frame.
 * A bold gradient frame around the page. The page itself is its own document:
 * style what is inside with a <style> block in the HTML.
 * Install: Appearance tab -> Enable Custom CSS -> paste this whole file.
 */

.custom-widget {
	background:
		linear-gradient(165deg, #241539, #120c22 72%) padding-box,
		linear-gradient(135deg, #f472b6, #facc15 48%, #38bdf8) border-box;
	border: 4px solid transparent;
	border-radius: 18px;
	padding: 6px;
	box-shadow: 0 16px 38px rgba(8, 4, 20, 0.55);
}

.html-frame {
	border-radius: 12px;
}

.net-prompt {
	background: rgba(36, 21, 57, 0.97);
	border-color: #f472b6;
}

.net-prompt-allow {
	background: #db2777;
}

/*
 * Terminal widget - "Amber Phosphor Frame" theme.
 * Dark brown backdrop, amber double frame with an outer glow and uppercase
 * amber loading text. Terminal text is painted by xterm.js on a canvas, so only
 * the frame can be themed. Install: Appearance tab -> Enable Custom CSS -> paste this.
 */

.terminal-widget {
	background:
		radial-gradient(circle at 50% 0%, rgba(255, 159, 28, 0.14), transparent 60%),
		linear-gradient(180deg, #1c1105 0%, #0c0703 100%);
	border: 1px solid #ff9f1c;
	border-radius: 12px;
	box-sizing: border-box;
	color: #ffc46b;
	padding: 7px;
	box-shadow:
		0 0 22px rgba(255, 159, 28, 0.35),
		inset 0 0 26px rgba(255, 159, 28, 0.12);
	animation: odeko-terminal-frame-glow 4s ease-in-out infinite;
}

@keyframes odeko-terminal-frame-glow {
	50% {
		box-shadow:
			0 0 34px rgba(255, 159, 28, 0.5),
			inset 0 0 30px rgba(255, 159, 28, 0.2);
	}
}

/* Inner frame line, drawn inside the amber padding so it never covers text. */
.terminal-widget::after {
	content: '';
	position: absolute;
	top: 3px;
	right: 3px;
	bottom: 3px;
	left: 3px;
	border: 1px solid rgba(255, 159, 28, 0.35);
	border-radius: 9px;
	pointer-events: none;
}

.terminal-container {
	border-radius: 8px;
}

.loading-overlay {
	border: 1px solid rgba(255, 159, 28, 0.3);
}

.loading-text {
	color: #ffb347;
	font-family: 'Courier New', Consolas, monospace;
	font-size: 0.9em;
	letter-spacing: 0.24em;
	text-shadow: 0 0 10px rgba(255, 159, 28, 0.75);
	text-transform: uppercase;
	animation: odeko-terminal-flicker 1.6s ease-in-out infinite;
}

@keyframes odeko-terminal-flicker {
	50% {
		opacity: 0.7;
	}
}
